/// <summary>
/// CB756_ValidationOfABNToATOSystem.
/// Batch service class for ABN validation.
/// </summary>
class METABNValidationJobService extends METSysOperationService
{
    private AddressCountryRegionId countryRegionId;
    private guid                   topPickingProcessId;
    private date                   todayDate;
    private TableId                taxVATNumTableId,
                                   taxRegistrationTableId;
}

Method.Source:
/// <summary>
/// Returns name of the task service class.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METABNValidationJobTaskService);
}

/// <summary>
/// Returns name of the task service class method.
/// </summary>
/// <returns>Task service class method name</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METABNValidationJobTaskService, process);
}

/// <summary>
/// Returns caption of the task service class.
/// </summary>
/// <returns>Task service class caption</returns>
protected str getTaskServiceCaption()
{
    return "@MET:ABNValidation";
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSysOperationTaskDataContract</c>
/// </param>
public void process(METABNValidationJobContract _contract)
{
    this.processInternal(_contract);
}

    /// <summary>
    /// Initialise global variables.
    /// </summary>
    public void initialise()
    {
        super();

        this.stageDataIntoQueue();
    }

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    METABNValidationJobContract contract = _taskDataContract as METABNValidationJobContract;
    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METABNValidationJobContract();
}

    /// <summary>
    /// Stages data int table <c>METABNValidationJobQueue</c>.
    /// </summary>
    void stageDataIntoQueue()
    {
        #OCCRetryCount

        METABNValidationJobContract contract;
        
        topPickingProcessId     = newGuid();
        todayDate               = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
        taxVATNumTableId        = tableNum(TaxVATNumTable);
        taxRegistrationTableId  = tableNum(TaxRegistration);
        countryRegionId         = CompanyInfo::find().postalAddress().CountryRegionId;
        contract                = dataContract as METABNValidationJobContract;
                              
        try
        {
            ttsbegin;

            METABNValidationJobQueue::cleanUpABNValidationJobQueue();

            if (contract.checkQueryFilterValue())
            {
                this.stageDataIntoQueueQueryFiltered(contract.getQuery(), contract.parmMonths());
            }
            else
            {
                this.stageDataIntoQueueMonthsFiltered(contract.parmMonths());
            }

            ttscommit;

        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Error)
        {
            // catch the errors so processing can continue
            curext(); // avoids a warning about an empty block
        }
    }

    /// <summary>
    /// Stages <c>Query</c> filtered data into <c>METABNValidationJobQueue</c>.
    /// </summary>
    /// <param name = "_query"> <c>Query</c>. </param>
    /// <param name = "_month"> months. </param>
    void stageDataIntoQueueQueryFiltered(Query _query, int _months)
    {
        METABNValidationJobQueue             abnValidationjobQueue;
        METABNValidationJobFilterTmp         abnValidationJobFilterTmp;
        TaxRegistration                      taxRegistration;
        TaxRegistrationTypeApplicabilityRule taxRegistrationTypeApplicabilityRule;
        DirPartyLocation                     dirPartyLocation;
        DirPartyTable                        dirPartyTable;
        CustTable                            customer;
        CredManAccountStatusTable            accountStatusTable;
        TaxVATNumTable                       taxVatNumTable;
        date                                 dateToFilter;

        dateToFilter = DateTimeUtil::date(DateTimeUtil::addMonths(DateTimeUtil::utcNow(), -_months));
        //Inserts data into TempTable from query. 
        //TempTable is going to be used in filteration of records.
        METABNValidationJobFilterTmp::insertDataFromQuery(abnValidationJobFilterTmp, _query);
        
        METABNValidationJobQueue::skip(abnValidationjobQueue);

        //RefRecId not populated for TaxVATNumTable because it doesn't contain a unique index for it.
        //Exists join with TempTable to insert records that are returned from the query.
        insert_recordset abnValidationJobQueue(ProcessId, RefTableId, ABN, CustAccount)
            select topPickingProcessId, taxVATNumTableId, VATNum, AccountNum from customer
                exists join accountStatusTable
                    where accountStatusTable.CustAccountStatusId == customer.CredManAccountStatusId
                    &&    accountStatusTable.METABNValidation != METABNValidationType::None
                exists join abnValidationJobFilterTmp
                    where customer.AccountNum == abnValidationJobFilterTmp.CustAccount
                exists join taxVatNumTable
                    where customer.VATNum == taxVatNumTable.VATNum
                    && ((!_months || _months && taxVatNumTable.METVerifiedDate <= dateToFilter)
                    ||  (taxVatNumTable.METVerifiedDate == dateNull()));

        //RefRecId populated only in case of TaxRegistration because it contains a unique index for it.
        //Exists join with TempTable to insert records that are returned from the query.
        insert_recordset abnValidationJobQueue(ProcessId, RefTableId, RefRecId, ABN, CustAccount)
            select validTimeState(todayDate) topPickingProcessId, taxRegistrationTableId, RecId, RegistrationNumber from taxRegistration
                where ((!_months || _months && taxRegistration.METVerifiedDate <= dateToFilter)
                    || (taxRegistration.METVerifiedDate == dateNull()))
                join taxRegistrationTypeApplicabilityRule
                    where taxRegistration.TaxRegistrationTypeApplicabilityRule == taxRegistrationTypeApplicabilityRule.RecId
                    &&    taxRegistrationTypeApplicabilityRule.METValidateABNWithATO == NoYes::Yes
                    &&    taxRegistrationTypeApplicabilityRule.CountryRegionId == countryRegionId
                join dirPartyLocation
                    where taxRegistration.DirPartyLocation == dirPartyLocation.RecId
                       && dirPartyLocation.IsPrimary == NoYes::Yes
                join dirPartyTable
                    where dirPartyLocation.Party == dirPartyTable.RecId
                join AccountNum from customer
                    where customer.Party == dirPartyTable.RecId
                exists join accountStatusTable
                    where accountStatusTable.CustAccountStatusId == customer.CredManAccountStatusId
                    &&    accountStatusTable.METABNValidation != METABNValidationType::None
                exists join abnValidationJobFilterTmp
                    where customer.AccountNum == abnValidationJobFilterTmp.CustAccount;
    }

    /// <summary>
    /// Stages months filtered data into <c>METABNValidationJobQueue</c>.
    /// </summary>
    /// <param name = "_months">Months.</param>
    void stageDataIntoQueueMonthsFiltered(int _months)
    {
        METABNValidationJobQueue             abnValidationjobQueue;
        TaxRegistration                      taxRegistration;
        TaxRegistrationTypeApplicabilityRule taxRegistrationTypeApplicabilityRule;
        DirPartyLocation                     dirPartyLocation;
        DirPartyTable                        dirPartyTable;
        CustTable                            customer;
        CredManAccountStatusTable            accountStatusTable;
        TaxVATNumTable                       taxVatNumTable;
        date                                 dateToFilter;
        
        //Calculates date to filter records on.
        dateToFilter = DateTimeUtil::date(DateTimeUtil::addMonths(DateTimeUtil::utcNow(), -_months));
        METABNValidationJobQueue::skip(abnValidationjobQueue);

        //RefRecId not populated for TaxVATNumTable because it doesn't contain a unique index for it.
        insert_recordset abnValidationJobQueue(ProcessId, RefTableId, ABN, CustAccount)
            select topPickingProcessId, taxVATNumTableId, VATNum, AccountNum from customer
                exists join accountStatusTable
                    where accountStatusTable.CustAccountStatusId == customer.CredManAccountStatusId
                    &&    accountStatusTable.METABNValidation != METABNValidationType::None
                exists join taxVatNumTable
                    where customer.VATNum == taxVatNumTable.VATNum
                    &&   ((!_months || _months && taxVatNumTable.METVerifiedDate <= dateToFilter)
                    ||     (taxVatNumTable.METVerifiedDate == dateNull()));

        //RefRecId populated only in case of TaxRegistration because it contains a unique index for it.
        insert_recordset abnValidationJobQueue(ProcessId, RefTableId, RefRecId, ABN, CustAccount)
            select validTimeState(todayDate) topPickingProcessId, taxRegistrationTableId, RecId, RegistrationNumber from taxRegistration
                where ((!_months || _months && taxRegistration.METVerifiedDate <= dateToFilter)
                    || (taxRegistration.METVerifiedDate == dateNull()))
                join taxRegistrationTypeApplicabilityRule
                    where taxRegistration.TaxRegistrationTypeApplicabilityRule  == taxRegistrationTypeApplicabilityRule.RecId
                    &&    taxRegistrationTypeApplicabilityRule.METValidateABNWithATO == NoYes::Yes
                    &&    taxRegistrationTypeApplicabilityRule.CountryRegionId == countryRegionId
                join dirPartyLocation
                    where taxRegistration.DirPartyLocation == dirPartyLocation.RecId
                       && dirPartyLocation.IsPrimary == NoYes::Yes
                join dirPartyTable
                    where dirPartyLocation.Party == dirPartyTable.RecId
                join AccountNum from customer
                    where customer.Party == dirPartyTable.RecId
                exists join accountStatusTable
                    where accountStatusTable.CustAccountStatusId == customer.CredManAccountStatusId
                    &&    accountStatusTable.METABNValidation != METABNValidationType::None;

    }
